import "../ns-worklet/text-codec-shim";
import registerNoiseSuppressionProcessor from "../ns-worklet/runtime";
// Generated by wasm-pack from libDF's `wasm` feature (see
// scripts/build-dfn3-worklet.sh); initSync + the df_* bindings.
import {
  df_create,
  df_get_frame_length,
  df_process_frame,
  initSync,
} from "./pkg/df";

registerNoiseSuppressionProcessor({
  engineRate: 48000,
  // DeepFilterNet3's hop size; asserted against the model at init.
  frameSize: 480,
  async createEngine({ wasm, model }) {
    // wasm-bindgen's async init() fetches by URL — unavailable here. The
    // bytes are compiled off-thread first so initSync only instantiates.
    initSync(await WebAssembly.compile(wasm));

    // 100dB attenuation limit == effectively uncapped.
    const state = df_create(new Uint8Array(model), 100);
    const hop = df_get_frame_length(state);
    if (hop !== 480) {
      throw new Error(`unexpected DeepFilterNet hop size: ${hop}`);
    }

    return {
      denoise(input, output) {
        output.set(df_process_frame(state, input));
      },
    };
  },
});
